import{_ as t}from"./chunks/settings-gamepad.pc.en.I-_X0Bx_.js";import{_ as o,o as a,c as n,a5 as s}from"./chunks/framework.D47SInms.js";const d="/RBQ/nightly/images/app/home-gamepad.mobile.en.png",b=JSON.parse('{"title":"Gamepad","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/gamepad.md","filePath":"manual/gui/gamepad.md","lastUpdated":1791600043000}'),i={name:"manual/gui/gamepad.md"};function r(h,e,c,l,p,u){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="gamepad" tabindex="-1">Gamepad <a class="header-anchor" href="#gamepad" aria-label="Permalink to &quot;Gamepad&quot;">​</a></h1><p>The app drives the robot with the on-screen virtual joysticks by default. Plug in or pair a physical gamepad and the app switches over automatically, with no setup step.</p><h2 id="automatic-detection" tabindex="-1">Automatic detection <a class="header-anchor" href="#automatic-detection" aria-label="Permalink to &quot;Automatic detection&quot;">​</a></h2><ul><li>Connect a gamepad over USB or Bluetooth. The app recognizes it immediately, applies a matching profile, and <strong>hides the virtual joysticks</strong>.</li><li>Unplug it and the virtual joysticks come back on their own.</li><li>While a gamepad is active, the only visible change on the control home is that the virtual joysticks are gone. The cards and the viewport stay where they are. The <code>Input</code> popover described below shows a live diagram of the device — its name, sticks, and buttons.</li></ul><p><img src="'+d+'" alt="Control home in gamepad mode — virtual joysticks hidden"></p><p>To check what is connected, open <strong>Settings</strong> (the <code>Settings</code> tile on the hub) › <code>Gamepad</code>. The status line reads <code>Connected</code> followed by the device name, or <code>No gamepad connected — using virtual joystick</code>. Below it, <code>Active profile:</code> shows which button/axis layout was picked <code>(auto-detected)</code>.</p><p><img src="'+t+'" alt="Gamepad settings"></p><h2 id="choosing-the-input-mode" tabindex="-1">Choosing the input mode <a class="header-anchor" href="#choosing-the-input-mode" aria-label="Permalink to &quot;Choosing the input mode&quot;">​</a></h2><p>Two places let you override the automatic choice:</p><ul><li><strong>Settings › <code>Gamepad</code> › <code>Joystick mode</code></strong> — <code>Auto</code> / <code>Virtual joystick</code> / <code>Gamepad</code>. This changes the <em>UI layout</em> only; whatever inputs are connected keep working.</li><li><strong>Control home › <code>Input</code></strong> (the gamepad button in the tool row outside the left card — just right of the left joystick, or at the left edge with a gamepad) — the same choice as <code>Auto</code> / <code>Virtual</code> / <code>Pad</code>. When a gamepad is connected (and the joystick mode is not set to <code>Virtual joystick</code>) this popover also shows a live diagram of what the app is receiving from it.</li></ul><p>Leave the mode on <code>Auto</code> unless you are troubleshooting.</p><h2 id="safe-button-set" tabindex="-1">Safe button set <a class="header-anchor" href="#safe-button-set" aria-label="Permalink to &quot;Safe button set&quot;">​</a></h2><p>Out of the box the app forwards only the two shoulder buttons (<strong>L1 / R1</strong>) to the robot together with the sticks. The app leaves the remaining buttons out of the joystick frame, so an accidental press cannot trigger a robot-side button action. Buttons a developer has mapped in <code>Button mapping</code>, and the <code>Cruise control</code> keys, still act no matter how this is set.</p><p>Entering <strong>developer mode</strong> turns <code>Send all buttons</code> on automatically, which forwards every button. Chords the robot reads together with a shoulder button, such as <strong>L1 + B</strong>, need this setting on. While it is off, the other half of the chord never reaches the frame, so nothing happens. Returning to the normal level restores the safe set. The toggle lives in <a href="/RBQ/nightly/manual/gui/developer-mode.html#gamepad">Developer mode</a>.</p><h2 id="typing-on-a-steam-deck" tabindex="-1">Typing on a Steam Deck <a class="header-anchor" href="#typing-on-a-steam-deck" aria-label="Permalink to &quot;Typing on a Steam Deck&quot;">​</a></h2><p>On a Steam Deck the app draws its own on-screen keyboard: tap any text field and it appears at the bottom of the screen. It types Korean, English, digits and symbols, and the popup you are editing moves up to stay above the keyboard. The field being edited is outlined in blue — there is no blinking cursor, because the keyboard deliberately does not take the focus.</p><p>The keyboard can be driven with the gamepad as well:</p><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td>D-pad</td><td>Move between keys</td></tr><tr><td><strong>A</strong></td><td>Press the selected key</td></tr><tr><td><strong>B</strong></td><td>Close the keyboard</td></tr><tr><td><strong>X</strong></td><td>Backspace</td></tr><tr><td><strong>Y</strong></td><td>Space</td></tr><tr><td><strong>L1</strong></td><td>Shift</td></tr><tr><td><strong>R1</strong></td><td>Switch Korean / English</td></tr></tbody></table><p><code>123</code> and <code>한</code> / <code>A</code> always show <strong>where the key takes you</strong>, not where you are, and leaving the number layout returns you to the language you used last. <code>✓</code> confirms: it presses the popup&#39;s own confirm button when there is one, and otherwise submits the field.</p><p>While the keyboard is open the gamepad belongs to it — the sticks and buttons do not reach the robot, so the robot cannot move while you pick letters. Other platforms keep using the operating system keyboard.</p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#gamepad">Developer mode</a>.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>Send all buttons</code> and <code>Cruise control</code> change what the robot does in response to button presses. Test in an open area after turning either on, and keep the E-STOP within reach.</p></div>',22)])])}const y=o(i,[["render",r]]);export{b as __pageData,y as default};
